/*------------------------------------------------------------------------------
* test_led.c : Skybrush light-command decode and colour conversion
*
* The frames here are produced by pymavlink (see the hex blobs), so a mistake
* in DEBUG_VECT's payload layout cannot pass. The PIO wire timing is verified
* separately on the target by led_strip_selftest().
*-----------------------------------------------------------------------------*/
#include "show_led.h"
#include "mavlink_min.h"
#include "test_util.h"
#include <string.h>
#include <stdio.h>

/* Generated by pymavlink, not transcribed: see tools/mavlink_wire.py.
 * DEBUG_VECT name="rgb" x=1.0 y=0.0 z=0.0, sysid=1 compid=1 */
static const uint8_t FRAME_RED[] = {
    0xfd,0x17,0x00,0x00,0x00,0x01,0x01,0xfa,0x00,0x00,
    0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
    0x80,0x3f,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
    0x72,0x67,0x62,0xce,0x02,
};
/* Same message, name "foo": a DEBUG_VECT that is not a light command. */
static const uint8_t FRAME_OTHER[] = {
    0xfd,0x17,0x00,0x00,0x00,0x01,0x01,0xfa,0x00,0x00,
    0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
    0x80,0x3f,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
    0x66,0x6f,0x6f,0x39,0xc5,
};

static void test_decode(void)
{
    const show_led_state_t *s;

    TEST_BEGIN("DEBUG_VECT \"rgb\" -> colour");
    show_led_init(false);
    s = show_led_state();

    CHECK(!show_led_handle_frame(FRAME_RED, 3, 0), "a truncated frame is ignored");
    CHECK(show_led_handle_frame(FRAME_RED, sizeof(FRAME_RED), 1000),
          "accepted a pymavlink-encoded DEBUG_VECT");
    CHECK(s->r == 255 && s->g == 0 && s->b == 0,
          "full red decoded as (%d,%d,%d)", s->r, s->g, s->b);
    CHECK(s->updates == 1, "update counter advanced");

    /* A DEBUG_VECT that is not a light command must be left alone. */
    CHECK(!show_led_handle_frame(FRAME_OTHER, sizeof(FRAME_OTHER), 1100),
          "DEBUG_VECT with another name is not a light command");
    CHECK(s->updates == 1, "and does not disturb the colour");
    /* Nor must an unrelated message type. */
    {
        const uint8_t hb[] = {0xfd,0x09,0x00,0x00,0x00,0x07,0x01,0x00,0x00,0x00,
                              0x05,0x00,0x00,0x00,0x02,0x03,0x51,0x04,0x03,0xb1,0x3a};
        CHECK(!show_led_handle_frame(hb, sizeof(hb), 1200), "HEARTBEAT ignored");
    }
}

static void test_conversion(void)
{
    uint8_t r, g, b, w;

    TEST_BEGIN("0..1 float -> channels, and RGB -> RGBW");

    show_led_convert(0.0f, 0.0f, 0.0f, false, &r, &g, &b, &w);
    CHECK(r == 0 && g == 0 && b == 0, "black");
    show_led_convert(1.0f, 1.0f, 1.0f, false, &r, &g, &b, &w);
    CHECK(r == 255 && g == 255 && b == 255 && w == 0, "white, RGB strip");
    show_led_convert(0.5f, 0.5f, 0.5f, false, &r, &g, &b, &w);
    CHECK(r == 128 && g == 128 && b == 128, "mid grey rounds to 128");

    /* out-of-range and NaN must clamp rather than wrap a uint8 */
    show_led_convert(2.0f, -1.0f, 0.0f/0.0f, false, &r, &g, &b, &w);
    CHECK(r == 255, "above 1.0 clamps to 255");
    CHECK(g == 0,   "below 0.0 clamps to 0");
    CHECK(b == 0,   "NaN clamps to 0 rather than wrapping");

    /* RGBW: white takes the neutral component, colours keep the remainder */
    show_led_convert(1.0f, 1.0f, 1.0f, true, &r, &g, &b, &w);
    CHECK(w == 255 && r == 0 && g == 0 && b == 0,
          "pure white drives only the W channel (%d,%d,%d,%d)", r, g, b, w);
    show_led_convert(1.0f, 0.5f, 0.5f, true, &r, &g, &b, &w);
    CHECK(w == 128 && r == 127 && g == 0 && b == 0,
          "pink splits into W=128 plus R=127 (%d,%d,%d,%d)", r, g, b, w);
    show_led_convert(1.0f, 0.0f, 0.0f, true, &r, &g, &b, &w);
    CHECK(w == 0 && r == 255, "saturated red leaves W dark");
}

static void test_timeout(void)
{
    const show_led_state_t *s;

    TEST_BEGIN("link loss blanks the LEDs");
    show_led_init(false);
    s = show_led_state();
    show_led_handle_frame(FRAME_RED, sizeof(FRAME_RED), 10000);
    CHECK(s->r == 255, "lit");
    CHECK(!show_led_tick(10500, 1000), "no change reported inside the timeout");
    CHECK(s->r == 255, "still lit inside the timeout");
    /* The return value is the whole point: the caller pushes to the strip only
     * when told something changed, so a tick that blanks silently leaves the
     * LEDs lit. */
    CHECK(show_led_tick(11500, 1000), "reports the change so the caller repaints");
    CHECK(s->r == 0 && s->g == 0 && s->b == 0,
          "blanked after the timeout rather than holding a stale colour");
    CHECK(!show_led_tick(12500, 1000), "does not report again once blanked");
    CHECK(s->blankings == 1, "blanking counted once");
}

int main(void)
{
    printf("RTKLIB Pico port - Skybrush LED tests\n");
    test_decode();
    test_conversion();
    test_timeout();
    TEST_SUMMARY();
    return g_tests_failed ? 1 : 0;
}
